:root {
  --bg: #070a10;
  --panel: rgba(10, 15, 24, 0.82);
  --panel-solid: #0b111c;
  --panel-elev: rgba(15, 23, 36, 0.88);
  --border: rgba(148, 163, 184, 0.18);
  --border-strong: rgba(148, 163, 184, 0.34);
  --text: #f1f5f9;
  --text-muted: #94a3b8;
  --text-dim: #64748b;

  /* Straitjacket Addressable Evidence semantic palette */
  --blue: #3b82f6;
  --blue-hi: #60a5fa;
  --blue-bg: rgba(59, 130, 246, 0.14);
  --amber: #f59e0b;
  --amber-hi: #fbbf24;
  --amber-bg: rgba(245, 158, 11, 0.14);
  --red: #ef4444;
  --red-hi: #f87171;
  --red-bg: rgba(239, 68, 68, 0.14);
  --green: #22c55e;
  --green-hi: #4ade80;
  --green-bg: rgba(34, 197, 94, 0.14);

  --font-display: 'Space Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-display);
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  overflow-x: hidden;
}

code,
pre,
.mono,
.tel-value,
.stat-figure,
.rail-btn {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

/* Fixed Full-Viewport 3D Canvas */
#stage {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  display: block;
  z-index: 0;
  pointer-events: none;
}

.webgl-fallback {
  position: fixed;
  inset: 0;
  z-index: 0;
  background: radial-gradient(circle at 68% 36%, rgba(37, 99, 235, 0.24), transparent 52%),
    radial-gradient(circle at 22% 78%, rgba(245, 158, 11, 0.14), transparent 46%),
    linear-gradient(180deg, #06090f 0%, #0a1220 100%);
}

/* Top Architectural HUD Header */
.hud-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 60px;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  background: rgba(7, 10, 16, 0.78);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  z-index: 40;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--text);
  text-decoration: none;
  white-space: nowrap;
}

.brand-icon {
  display: block;
  flex-shrink: 0;
}

.brand-word {
  font-weight: 700;
  letter-spacing: 0.14em;
  font-size: 0.88rem;
}

.brand-ver {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--amber-hi);
  padding: 2px 7px;
  border: 1px solid rgba(245, 158, 11, 0.35);
  background: var(--amber-bg);
  letter-spacing: 0.04em;
}

.hud-nav {
  display: flex;
  align-items: center;
  gap: 6px;
}

.hud-nav a {
  color: var(--text-muted);
  text-decoration: none;
  font-family: var(--font-mono);
  font-size: 0.74rem;
  padding: 6px 10px;
  border: 1px solid transparent;
  transition: color 0.18s ease, border-color 0.18s ease, background 0.18s ease;
}

