  grid-column: span 2;
  padding: 18px;
  background: rgba(11, 17, 28, 0.9);
  border: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.receipt-card:nth-child(1),
.receipt-card:nth-child(2) {
  grid-column: span 3;
  border-top: 2px solid var(--blue);
}

.receipt-card:nth-child(2) {
  border-top-color: var(--green);
}

